"""Distinct service inputs and source-linked research planning guides."""
from html import escape

DESEQ='https://www.bioconductor.org/packages/release/bioc/vignettes/DESeq2/inst/doc/DESeq2.html'
MICRO='https://doi.org/10.1038/s41564-025-02035-2'
DETAILS={
'rna-seq-analysis':('Which genes change between your study groups?', ['Organism, assay and library preparation; confirm whether the request concerns bulk RNA-seq. Single-cell and other assays need a separate design review.','Starting point: FASTQ reads, quantification files or an unnormalized count matrix; include reference and annotation versions.','Sample metadata, biological replicates, batches, paired subjects and proposed contrasts.'], 'A counts-only starting point cannot repeat read-level QC. Confounded designs and absent replication can limit the comparisons supported. Enrichment depends on the reference and gene universe.', DESEQ),
'metagenomics-analysis':('How does microbial composition differ across your samples?', ['State whether inputs are marker-gene amplicons or shotgun reads; provide sample type, read layout and sequencing information.','Provide sample metadata, groups, repeated measures, extraction batches and available negative or positive controls.','For amplicons, include target region and primers. For shotgun requests, discuss host reads, reference coverage and whether profiling or assembly is appropriate.'], 'Taxonomic resolution depends on assay and references. Relative abundance is not an absolute cell count. Contamination can dominate low-biomass samples; missing controls constrain interpretation. Functional inference and direct measurement are distinct.', MICRO),
'bioinformatics-consulting':('What computational decision needs to be made next?', ['A focused biological question and the decision you need the analysis to inform.','An inventory of available files, previous methods, software versions and existing reports.','Known constraints on data access, compute, budget, timing and team responsibilities.'], 'A feasibility review may recommend a narrower question or further data collection. A written method plan is distinct from implementing and validating a production workflow.', DESEQ),
'scientific-data-analysis':('Which comparison can your study design support?', ['A data dictionary with units, variable types, missing-value codes and experimental units.','Study groups, biological versus technical replicates, repeated measurements, exclusions and intended comparisons.','Existing summaries and the provenance of derived variables; use non-sensitive examples during initial review.'], 'Models require suitable observations and assumptions. Association alone does not establish causation. Small samples, multiplicity and selection can constrain inference; report effect sizes and uncertainty where appropriate.', DESEQ),
'scientific-figure-preparation':('What result must the reader understand?', ['Documented source tables and the method that produced them, including uncertainty and sample counts.','Intended comparisons, axis units, group labels and a draft caption.','Journal dimensions and export requirements, preferred editable source format and the revision scope.'], 'Figure preparation does not validate an upstream analysis. Disclose transformations and exclusions; avoid selectively hiding observations or presenting exploratory patterns as confirmed findings.', DESEQ),
'python-research-automation':('Which recurring research task needs a reliable script?', ['A representative non-sensitive input, an expected output and a description of each transformation.','File formats, anticipated scale, operating environment and dependencies.','Examples of malformed inputs, validation rules and the rerun or handover requirements.'], 'A local script is not automatically a production pipeline. Workflow frameworks, scheduling, deployment, monitoring and long-term maintenance require separate capability and scope review.', 'https://docs.python.org/3/library/venv.html')}

def service_detail(slug):
    question,inputs,limits,ref=DETAILS[slug]
    return '<section><h2>'+escape(question)+'</h2><h3>Bring these inputs to scoping</h3><ul>'+''.join('<li>'+escape(i)+'</li>' for i in inputs)+'</ul><h3>Prerequisites and interpretation limits</h3><p>'+escape(limits)+'</p><p><a href="'+ref+'">Method reference</a> · <a href="/resources/">Research planning guides</a></p></section>'

GUIDES=[
('rna-seq-quote','What to send for an RNA-seq analysis quote','rna-seq-analysis',[
('Start with the question','Describe the organism, biological comparison and why it matters. Name the assay and library preparation. Bulk RNA-seq, single-cell data and de novo transcriptomes require different reviews; do not assume one workflow fits all.'),
('Describe the study design','List groups, biological replicates, paired subjects, batches and planned contrasts. Explain how samples were collected and which variables could affect interpretation. If group and batch coincide, more computation cannot recover a missing comparison.'),
('Inventory the files','Say whether you have FASTQ reads, quantification files or a raw count matrix. Note approximate file sizes, reference assembly and annotation versions. Prepare a sample sheet whose identifiers match the files. Send file descriptions first, rather than confidential raw data.'),
('Agree the deliverables','Discuss read-level QC when reads are available, design review, analysis tables, figures and interpretation. Include scripts, configuration, methods notes and rerun requirements in the scope. Identify compute charges and revision boundaries before starting.'),
('Limitations','A quote is conditional on the input inventory and feasibility review. No analysis promises significance or publication. Missing metadata or unsuitable replication may narrow the questions that can be answered.')],DESEQ),
('fastq-versus-count-matrix','FASTQ versus count matrix: how the starting point changes scope','rna-seq-analysis',[
('Starting with reads','FASTQ inputs allow a read-level workflow to be scoped: quality assessment, preprocessing where justified, alignment or quantification and downstream analysis. Exact stages depend on the assay, organism, references and design.'),
('Starting with counts','A gene count matrix begins downstream of read processing. Supply sample metadata and how counts were generated, including reference and annotation. A matrix cannot by itself establish that reads were suitable or sample identities were correct.'),
('Counts are not interchangeable','DESeq2 expects suitable unnormalized counts with the relevant sample information and design. TPM, FPKM and transformed expression values are not direct substitutes for raw count input. Quantifier imports require an appropriate documented route.'),
('What the quote needs','State the starting files, their provenance, number of samples, comparisons and expected outputs. Separate any rerun of upstream processing from downstream interpretation. Discuss whether original reads remain available if QC questions arise.'),
('Limitations','This guide describes planning for a common bulk RNA-seq setting. Other assays and statistical methods have different input assumptions. Choose methods with a study-specific review.')],DESEQ),
('microbiome-analysis-planning','Planning microbiome analysis: amplicon or shotgun?','metagenomics-analysis',[
('Identify the assay','Marker-gene amplicon and shotgun sequencing observe different aspects of a community. Report sample type, extraction method, read layout and the biological question before choosing an analysis.'),
('Bring the controls','Include available extraction blanks, negative controls, positive controls and batch metadata. Low-biomass samples require particular care: background contamination can affect the apparent community and the conclusions.'),
('Set the comparison','Describe groups, paired or repeated samples and relevant covariates. Discuss whether the question concerns composition, diversity, a specific taxon or functional evidence. Avoid selecting tests solely because a plot looks different.'),
('Scope outputs separately','Amplicon requests should identify primers and target region; shotgun requests should discuss host sequence handling, reference coverage and profiling versus assembly. Ask for QC, annotated outputs, methods and explicit inference limits.'),
('Limitations','Relative sequence abundance does not directly measure absolute cell numbers. Missing controls and batch confounding cannot always be repaired later. Functional predictions require clear labeling and do not replace direct measurements.')],MICRO),
('reproducible-handover','What a reproducible bioinformatics handover should contain','python-research-automation',[
('Record the inputs','Agree a manifest, sample metadata, file checksums where appropriate, reference identifiers and provenance. Keep sensitive data in the agreed storage route rather than a public repository.'),
('Record the environment','Include software versions and installation or environment instructions. A Python virtual environment helps isolate dependencies; it does not by itself document all system tools, data resources or compute assumptions.'),
('Make rerunning explicit','Provide commands or entry points, configuration, required resources and the expected outputs. Document manual steps and external dependencies. Agree whether a fresh-environment rerun is included and on which representative data.'),
('Explain the results','The README should connect the question, design, methods, tables and figures. Report checks, exclusions, assumptions and limitations. A collection of scripts without these links is difficult to interpret.'),
('Agree rights and support','Specify code licenses, data permissions, compute costs, revision rounds and maintenance arrangements in writing. A reproducible handover does not imply indefinite support or guaranteed compatibility with future software versions.')],'https://docs.python.org/3/library/venv.html'),
('manuscript-figures-methods','Preparing figures and methods for a manuscript or reviewer response','scientific-figure-preparation',[
('Trace each figure','Connect every panel to a source table and the analysis that generated it. Record units, transformations, exclusions, sample counts and how uncertainty is displayed. Preserve original outputs separately.'),
('Clarify the question','Identify whether a panel shows an exploratory pattern, an effect estimate or a formal comparison. For differential expression figures, retain the model design, contrast and multiple-testing decisions in methods notes.'),
('Prepare readable exports','Agree target dimensions, readable labels, accessible color choices and vector or resolution requirements. Provide plotting source when included in scope so small editorial changes do not require recreating the analysis.'),
('Respond to reviewers with provenance','List each requested analysis, the files and code affected, and what changed in the text or figure. Distinguish additional analyses from presentation edits. Do not alter underlying values to fit an expected story.'),
('Limitations','Figure preparation cannot repair an unsupported design or validate biological conclusions. Additional tests may need new assumptions or a revised scope. Authorship, approval and submission remain matters for the research team.')],DESEQ)
]

def build_guides(page):
    for slug,title,service,sections,reference in GUIDES:
        body='<div class="eyebrow">Research planning · reviewed 8 November 2026</div><h1>'+escape(title)+'</h1><p class="intro">Prepare a focused analysis conversation without sharing confidential files.</p>'
        for heading,paragraph in sections:body+='<section><h2>'+escape(heading)+'</h2><p>'+escape(paragraph)+'</p></section>'
        body+='<section><h2>Reference and next step</h2><p>Editorial planning guide prepared by ANGSUMI; this is not a report of original research or a claim of independent scientific review.</p><p><a href="'+reference+'">Read the underlying method documentation or research guidance</a></p><p><a href="/services/'+service+'/">Review the related service</a></p><a class="btn" href="/inquiry/?category=research&amp;service='+service+'">Discuss my dataset →</a></section>'
        page('resources/'+slug,title,'Planning guidance: '+title+'. Inputs, scope decisions and interpretation limits for research analysis.',body)
